package dev.thillainirmal.cloudpulse;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;
class PulseAnalyzerTest{PulseAnalyzer a=new PulseAnalyzer();@Test void healthySnapshot(){var r=a.analyze(new PulseAnalyzer.Snapshot("n","w",30,40,.2,120,0));assertThat(r.status()).isEqualTo("HEALTHY");assertThat(r.findings()).isEmpty();}@Test void detectsCrashLoop(){var r=a.analyze(new PulseAnalyzer.Snapshot("n","w",91,94,8,1200,5));assertThat(r.status()).isEqualTo("CRITICAL");assertThat(r.probableCause()).contains("memory");assertThat(r.findings()).hasSize(5);}@Test void keepsActionsReadOnly(){var r=a.analyze(new PulseAnalyzer.Snapshot("n","w",90,50,0,100,0));assertThat(r.findings().get(0).action()).contains("Inspect");assertThat(r.trace()).anyMatch(x->x.contains("blocked"));}}
